import sys,json
sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/dev')
import analyze as AN
from fractions import Fraction
import randtest3 as G
def wcheck(req,w,k):
    assert len(w['demands'])==len(req['snapshots'])
    assert len(w['links'])==len(req['snapshots'])
    faulty=set()
    for s,q,links in zip(req['snapshots'],w['demands'],w['links']):
        assert len(q)==len(req['commodities'])
        assert all(type(v) is int and lo<=v<=hi for v,(lo,hi) in zip(q,s['bounds']))
        loads={e['id']:Fraction(0) for e in req['edges']}
        metrics={}
        for c,v in zip(req['commodities'],q):
            metrics['demand',c['id']]=v
            W=sum(r['weight'] for r in c['routes'])
            for r in c['routes']:
                amt=Fraction(v*r['weight'],W)
                for e in r['edges']: loads[e]+=amt
        for n in req['nodes']:
            metrics['ingress',n]=sum(v for c,v in zip(req['commodities'],q) if c['source']==n)
            metrics['egress',n]=sum(v for c,v in zip(req['commodities'],q) if c['target']==n)
        metrics.update({('link',e):v for e,v in loads.items()})
        assert links==["%d/%d"%(loads[e['id']].numerator,loads[e['id']].denominator) for e in req['edges']]
        assert all(loads[e['id']]<=e['capacity'] for e in req['edges'])
        for o in s['observations']:
            if not Fraction(o['lower'])<=metrics[o['metric'],o['target']]<=Fraction(o['upper']):
                assert o['domain'] is not None
                faulty.add(o['domain'])
    assert sorted(w['faults'])==sorted(faulty)
    assert len(faulty)==k

bad=0
for seed in range(300):
    req=G.gen(seed)
    try: norm=AN.validate(req)
    except Exception: continue
    res=AN.solve(norm)
    if res.get('status') in ('unique','ambiguous'):
        try:
            wcheck(req,res['witness'],res['min_faults'])
            if res['status']=='ambiguous':
                assert res['alternative'] is not None, 'no alternative'
                wcheck(req,res['alternative'],res['min_faults'])
                assert res['witness']['demands']!=res['alternative']['demands'],'alt same'
            else:
                assert res.get('alternative') is None
        except Exception as e:
            bad+=1; print('BAD',seed,repr(e)); 
            if bad>5: break
print('witness check done bad=',bad)
